from pathlib import Path
import subprocess


def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = path.read_text()
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label} anchor changed: {count}")
    path.write_text(text.replace(old, new, 1))


path = Path("src/4_semantics/global/call_compatibility.zig")
replace_once(
    path,
    '''        const score = switch (matchInput(compatibility, function.input, input_node)) {\n            .no_match => continue,\n            .deferred => {\n                saw_deferred = true;\n                continue;\n            },\n            .score => |score| score,\n        };\n''',
    '''        const input_match = matchInput(compatibility, function.input, input_node);\n        if (std.mem.eql(u8, name, "make_tracked")) {\n            const graph = compatibility.core.graph;\n            const literal = switch (graph.nodes.items[@intFromEnum(input_node)].content) {\n                .struct_value_literal => |value| value,\n                else => {\n                    std.debug.print("[make-tracked] non-struct input\\n", .{});\n                    continue;\n                },\n            };\n            std.debug.print(\n                "[make-tracked] function={} fields={}+{} supplied={}+{} names-match={} result={s}\\n",\n                .{\n                    raw,\n                    function.input.start,\n                    function.input.len,\n                    literal.fields.start,\n                    literal.fields.len,\n                    compatibility.core.callInputNamesMatch(function.input, literal),\n                    @tagName(input_match),\n                },\n            );\n            for (0..function.input.len) |expected_offset| {\n                const expected = graph.fields.items[function.input.start + @as(u32, @intCast(expected_offset))];\n                const supplied = callArgument(graph, literal, expected_offset, expected.name);\n                if (supplied) |node| {\n                    const supplied_node = graph.nodes.items[@intFromEnum(node)];\n                    if (supplied_node.ty) |actual| {\n                        const core_compatible = compatibility.core.callTypesCompatible(actual, expected.ty);\n                        const abstract_compatible = compatibility.compatible(actual, expected.ty);\n                        const literal_compatible = contextualLiteralFits(compatibility, node, expected.ty);\n                        std.debug.print(\n                            "[make-tracked-field] name={s} node={} actual={}({s}) expected={}({s}) exact={} core={} abstract={} literal={}\\n",\n                            .{\n                                graph.text(expected.name),\n                                @intFromEnum(node),\n                                @intFromEnum(actual),\n                                @tagName(graph.types.items[@intFromEnum(actual)]),\n                                @intFromEnum(expected.ty),\n                                @tagName(graph.types.items[@intFromEnum(expected.ty)]),\n                                types.equal(graph, actual, expected.ty),\n                                core_compatible,\n                                abstract_compatible,\n                                literal_compatible,\n                            },\n                        );\n                        if (graph.types.items[@intFromEnum(actual)] == .pointer and graph.types.items[@intFromEnum(expected.ty)] == .pointer) {\n                            const actual_child = graph.types.items[@intFromEnum(actual)].pointer.child;\n                            const expected_child = graph.types.items[@intFromEnum(expected.ty)].pointer.child;\n                            const actual_name: []const u8 = switch (graph.types.items[@intFromEnum(actual_child)]) {\n                                .declared => |decl| graph.text(graph.declarations.items[@intFromEnum(decl)].name),\n                                .generic => |generic| graph.text(graph.declarations.items[@intFromEnum(generic.base)].name),\n                                else => "<non-nominal>",\n                            };\n                            const expected_name: []const u8 = switch (graph.types.items[@intFromEnum(expected_child)]) {\n                                .declared => |decl| graph.text(graph.declarations.items[@intFromEnum(decl)].name),\n                                .generic => |generic| graph.text(graph.declarations.items[@intFromEnum(generic.base)].name),\n                                else => "<non-nominal>",\n                            };\n                            std.debug.print(\n                                "[make-tracked-pointee] actual={}({s}:{s}) expected={}({s}:{s}) implements={}\\n",\n                                .{\n                                    @intFromEnum(actual_child),\n                                    @tagName(graph.types.items[@intFromEnum(actual_child)]),\n                                    actual_name,\n                                    @intFromEnum(expected_child),\n                                    @tagName(graph.types.items[@intFromEnum(expected_child)]),\n                                    expected_name,\n                                    compatibility.abstracts.concreteImplements(actual_child, expected_child),\n                                },\n                            );\n                        }\n                    } else {\n                        std.debug.print("[make-tracked-field] name={s} node={} untyped literal={}\\n", .{ graph.text(expected.name), @intFromEnum(node), contextualLiteralFits(compatibility, node, expected.ty) });\n                    }\n                } else {\n                    std.debug.print("[make-tracked-field] name={s} missing default={}\\n", .{ graph.text(expected.name), expected.default_value != null });\n                }\n            }\n        }\n        const score = switch (input_match) {\n            .no_match => continue,\n            .deferred => {\n                saw_deferred = true;\n                continue;\n            },\n            .score => |score| score,\n        };\n''',
    "trace make_tracked candidate matching",
)
subprocess.run(["zig", "fmt", str(path)], check=True)
Path(".git/semantic-refactor-message").write_text("Trace make_tracked call matching")
Path(".git/semantic-refactor-test-command").write_text(
    "zig build test-programs -Dtest-filter=feature_tests/collections/26_dynamic_array_owning_pop\n"
)
